api.look('agent');
const w=api.w, cy=400;
const x0=60, x1=w-60;
const X=i=>x0+(x1-x0)*i/4;
api.line(x0,cy,x1,cy,{c:'fg',w:6});
const days=['Mon','Tue','Wed','Thu','Fri'];
const icons=['bulb','gear','gear','person','bolt'];
const names=['Design','Build','Build','Test','Ship'];
days.forEach((d,i)=>{
  const kk=api.stag(t,i,{gap:0.7,dur:0.6,from:0.2});
  const up=i%2===0?-1:1;
  api.line(X(i),cy,X(i),cy+up*90,{c:'dim',k:kk});
  api.circle(X(i),cy+up*140,48,{c:i<3?'accent':'a2',w:4,fill:'panel',k:kk});
  api.shape(icons[i],X(i),cy+up*140,48,{c:i<3?'accent':'a2',k:kk});
  api.text(names[i],X(i),cy+up*(up<0?215:215)+(up<0?-20:20),{size:20,weight:'bold',align:'center',k:kk});
  api.dot(X(i),cy,14,{k:1});
  api.text(d,X(i),cy+(up<0?36:-24),{size:16,c:'dim',align:'center'});
});
api.callout('New onboarding',X(0),cy-140,120,170,{k:api.seg(t,3.6,4.6)});
api.callout('5 users',X(3),cy+140,w-110,cy+300,{k:api.seg(t,4,5)});
api.say('Design, build, test, ship',0.3,5.5);

api.look('agent');
const w=api.w, cy=400;
const x0=60, x1=w-60;
const X=i=>x0+(x1-x0)*i/4;
const pk=api.seg(t,0,1.8);
api.line(x0,cy,x1,cy,{c:'dim',w:6});
api.line(x0,cy,X(2),cy,{c:'accent',w:8,k:pk});
const names=['Design','Build','Build','Test','Ship'];
const days=['Mon','Tue','Wed','Thu','Fri'];
days.forEach((d,i)=>{
  const done=i<2, now=i===2;
  const col=done?'good':now?'accent':'dim';
  api.circle(X(i),cy,24,{c:col,w:4,fill:done?'good':'panel'});
  if(done) api.shape('check',X(i),cy,26,{c:'ink',w:4,k:api.seg(t,0.3+i*0.5,0.9+i*0.5)});
  api.text(d,X(i),cy+60,{size:20,weight:'bold',align:'center',c:now?'accent':'fg'});
  api.text(names[i],X(i),cy-60,{size:16,align:'center',c:'dim'});
});
const wx=X(2), pul=api.pulse(t,1.2);
api.glow(wx,cy,60+pul*20,{c:'accent'});
api.circle(wx,cy,24+pul*8,{c:'accent',w:4});
api.text('We are here',wx,cy-150,{size:34,weight:'bold',align:'center',c:'accent',k:api.seg(t,2,3)});
api.arrow(wx,cy-120,wx,cy-45,{c:'accent',k:api.seg(t,2.3,3.2)});
api.progress(60,cy+190,w-120,22,0.5,{k:api.seg(t,3,4.5)});
api.text('Half way',w/2,cy+250,{size:22,align:'center',k:api.seg(t,3.5,4.5)});
api.say('We are at Wednesday',0.4,5.5);

api.look('agent');
const w=api.w, cy=400;
const x0=60, x1=w-60;
const X=i=>x0+(x1-x0)*i/4;
api.cam(api.lerp(0,-60,api.ease(api.seg(t,0,2))),0,api.lerp(1,1.15,api.ease(api.seg(t,0,2))),0);
api.line(x0,cy,x1,cy,{c:'dim',w:6});
api.line(x0,cy,X(2),cy,{c:'accent',w:8});
for(let i=0;i<5;i++){
  api.circle(X(i),cy,i<3?24:20,{c:i<2?'good':i===2?'accent':'dim',w:4,fill:i<2?'good':'panel'});
}
api.arrow(X(2)+30,cy-20,X(3)-30,cy-20,{c:'accent',k:api.seg(t,0.5,1.6),bend:-0.4});
api.along([[X(2),cy],[X(3),cy],[X(4),cy]],10,t,{c:'accent'});
const u=api.seg(t,1.5,3.5);
for(let i=0;i<5;i++){
  const kk=api.stag(t,i,{gap:0.3,dur:0.4,from:2});
  api.shape('person',X(3)-60+i*30,cy+110,34,{c:'a2',k:kk});
}
api.text('5 users',X(3),cy+170,{size:22,weight:'bold',align:'center',c:'a2',k:api.seg(t,2.8,3.8)});
api.shape('bolt',X(4),cy-90,48,{c:'a3',k:api.seg(t,3.5,4.5)});
api.text('Ship',X(4),cy-140,{size:22,weight:'bold',align:'center',c:'a3',k:api.seg(t,3.5,4.5)});
api.say('Next: test, then ship',0.4,5.5);
